import {api,escape as e,requestId} from './workspace-shared.js';
import {assignmentStatus,markingQueue,nextUnmarked} from './assignment-model.mjs';
const style=document.createElement('link');style.rel='stylesheet';style.href='/assignments.css?v=20261108-assignments';document.head.append(style);
const date=value=>value?new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(value):'No due date';
const btn=(label,attrs='',secondary=false)=>`<button type="button" class="teacher-button${secondary?' secondary':''}" ${attrs}>${label}</button>`;
const path=(cid,aid='')=>'/api/assignments/classes/'+encodeURIComponent(cid)+(aid?'/'+encodeURIComponent(aid):'');
export function createAssignments({root,teacher=false,parent=false,onChange=()=>{}}){
 let cid='',data,userId='',epoch=0,busy=false,detail=null,filter='submitted',selected='',history='',page='',frame=null,frameReady=false,frameError='',pending=new Map();
 const dialog=document.createElement('dialog');dialog.className='assignment-dialog';dialog.setAttribute('aria-label','Assignment workspace');document.body.append(dialog);
 const feedbackDrafts=new Map(),seenVersions=new Map();
 const draftKey=()=>['assignment-feedback',userId,cid,detail?.assignment.id,selected,current()?.attempt].join(':');
 function feedbackValue(row){const key=draftKey();try{return feedbackDrafts.get(key)??localStorage.getItem(key)??row.feedback;}catch{return feedbackDrafts.get(key)??row.feedback;}}
 const message=document.createElement('p');message.className='assignment-message';message.setAttribute('role','status');
 async function call(url,body,options){const result=await api(url,body?{...body,requestId:body.requestId||requestId(),expectedUserId:userId}:undefined,options);if(userId&&result.userId&&userId!==result.userId)throw Error('Your account changed. Reload this page.');userId=result.userId||userId;return result;}
 const error=err=>{message.textContent=err.message;message.setAttribute('role','alert');};
 const notify=text=>{message.textContent=text;message.setAttribute('role','status');};
 async function action(fn){if(busy)return;busy=true;dialog.setAttribute('aria-busy','true');try{await fn();}catch(err){error(err);}finally{busy=false;dialog.removeAttribute('aria-busy');}}
 function mount(html){dialog.innerHTML=html;dialog.append(message);dialog.querySelector('[data-close]').onclick=()=>action(close);}
 function popup(){if(!dialog.open)dialog.showModal();notify('');}
 async function flush(){
  if(!frame)return;if(!frameReady)throw Error(frameError||'Wait for the notebook page to load before continuing.');
  const id=requestId();await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{pending.delete(id);reject(Error('The notebook page did not confirm it was saved. Keep this window open and try again.'));},25000);pending.set(id,{resolve:version=>{clearTimeout(timer);if(frame?.dataset.attempt)seenVersions.set(frame.dataset.attempt+':'+frame.dataset.page,version);resolve();},reject:err=>{clearTimeout(timer);reject(err);}});frame.contentWindow.postMessage({type:'assignment:flush',id},location.origin);});
 }
 window.addEventListener('message',event=>{if(event.origin!==location.origin||event.source!==frame?.contentWindow)return;const m=event.data;if(m?.type==='assignment:ready'){frameReady=true;frameError='';if(frame?.dataset.attempt)seenVersions.set(frame.dataset.attempt+':'+frame.dataset.page,m.version);}if(m?.type==='assignment:error'){frameError=m.message;error(Error(m.message));}if(m?.type==='assignment:flushed'){const wait=pending.get(m.id);if(wait){pending.delete(m.id);m.ok?wait.resolve(m.version):wait.reject(Error(m.message||'Save did not complete.'));}}});
 async function close(){await flush();frame=null;frameReady=false;detail=null;dialog.close();onChange();}
 dialog.addEventListener('cancel',event=>{event.preventDefault();action(close);});
 function clearFrame(){frame=null;frameReady=false;frameError='';}
 function displayFrame(host,lid,pid,attempt,readOnly=false){clearFrame();if(!pid){host.innerHTML='<div class="assignment-empty">No notebook page in this submission.</div>';return;}
  frame=document.createElement('iframe');frame.title='Notebook page';frame.dataset.page=pid;frame.dataset.attempt=attempt||'';frame.src='/assignment-page?'+new URLSearchParams({classId:cid,assignmentId:detail.assignment.id,learnerId:lid,pageId:pid,...(attempt?{attempt}:{mode:'work'}),...(readOnly?{readOnly:'1'}:{})});host.replaceChildren(frame);
 }
 function counts(a){return `<div class="assignment-counts">${btn(`${a.counts.submitted} submitted`,`data-open="${e(a.id)}" data-filter="submitted"`,true)}${btn(`${a.counts.outstanding} unfinished`,`data-open="${e(a.id)}" data-filter="outstanding"`,true)}<span>${a.counts.reviewed} reviewed · ${a.counts.total} students</span></div>`;}
 function list(){
  const active=data.assignments.filter(a=>a.state==='active').sort((a,b)=>(a.dueAt||Infinity)-(b.dueAt||Infinity)),drafts=data.assignments.filter(a=>a.state==='draft');
  root.innerHTML=`<div class="assignment-heading"><div><h2>Assignments</h2><p>One submission per student. Notebook pages stay together.</p></div><div class="assignment-actions">${btn('Suggest from unit plan','data-suggest',true)}${btn('+ New assignment','data-new')}</div></div><p class="assignment-list-status" role="status"></p><div class="assignment-timeline">${active.length?active.map(a=>`<article class="assignment-row"><div><button class="assignment-title" type="button" data-open="${e(a.id)}">${e(a.title)}</button><p>Assigned ${e(date(a.assignedAt))} <span>→</span> Due ${e(date(a.dueAt))}</p></div>${counts(a)}</article>`).join(''):'<div class="assignment-empty">No assignments yet. Save a draft, then choose who receives it.</div>'}</div><details class="assignment-drafts" ${drafts.length?'open':''}><summary>Teacher drafts · ${drafts.length}</summary><p>Students and parents cannot see these until you assign them.</p>${drafts.map(a=>`<article class="assignment-row"><div><strong>${e(a.title)}</strong><p>${a.sourceKey?'Suggested from unit plan · ':''}${e(a.type==='reading'?'Reading confirmation':'Notebook work')} · ${e(date(a.dueAt))}</p></div>${btn('Review draft',`data-edit="${e(a.id)}"`,true)}</article>`).join('')}</details>`;
  root.querySelector('[data-new]').onclick=()=>edit();root.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(data.assignments.find(a=>a.id===b.dataset.edit)));
  root.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>open(cid,b.dataset.open,b.dataset.filter||'submitted'));
  root.querySelector('[data-suggest]').onclick=async event=>{const button=event.currentTarget;button.disabled=true;const status=root.querySelector('.assignment-list-status');status.textContent='Preparing private drafts from the saved unit plan…';try{await call(path(cid),{action:'suggest'},{timeoutMs:100000});await load(cid);root.querySelector('.assignment-list-status').textContent='Suggestions saved as teacher drafts. Review each before assigning.';}catch(err){status.textContent=err.message;button.disabled=false;}};
 }
 async function load(id){const version=++epoch;cid=id;root.textContent='Loading assignments…';try{const result=await call(path(id));if(version!==epoch)return;data=result;list();}catch(err){if(version===epoch){root.textContent=err.message;const retry=document.createElement('button');retry.textContent='Retry';retry.className='teacher-button';retry.onclick=()=>load(id);root.append(retry);}}}
 function edit(a){
  clearFrame();detail=null;const value=a||{id:requestId(),title:'',instructions:'',type:'written',lessonId:'',dueAt:null};
  const local=value.dueAt?new Date(value.dueAt-new Date(value.dueAt).getTimezoneOffset()*60000).toISOString().slice(0,16):'';
  mount(`<div class="assignment-modal-head"><h2>${a?'Review draft':'New assignment'}</h2>${btn('Close','data-close',true)}</div><form class="assignment-form"><label>Title<input name="title" required maxlength="160" value="${e(value.title)}"></label><label>Instructions<textarea name="instructions" rows="6" maxlength="8000">${e(value.instructions)}</textarea></label>${value.sourceKey?`<p class="assignment-source">AI suggestion — check the instructions before assigning.${value.sourceQuote?'<br>Unit plan: '+e(value.sourceQuote):''}</p>`:''}<div class="assignment-form-pair"><label>Submission<select name="type"><option value="written" ${value.type==='written'?'selected':''}>Notebook pages</option><option value="reading" ${value.type==='reading'?'selected':''}>Reading confirmation</option></select></label><label>Link to timeline lesson<select name="lessonId"><option value="">No linked lesson</option>${(data.lessons||[]).map(l=>`<option value="${e(l.id)}" ${value.lessonId===l.id?'selected':''}>${e(l.title)}</option>`).join('')}</select></label><label>Due date · your local time<input name="dueAt" type="datetime-local" value="${e(local)}"></label></div><p>Saving creates a private draft. Assigning is a separate step.</p><div class="assignment-actions"><button class="teacher-button" type="submit">Save draft</button>${a?btn('Choose students & assign','data-assign',true):''}</div></form>`);popup();
  const form=dialog.querySelector('form');form.onsubmit=event=>{event.preventDefault();action(async()=>{const fields=Object.fromEntries(new FormData(form));await call(path(cid,a?.id),{...fields,action:'save',id:value.id,revision:value.revision,dueAt:fields.dueAt?new Date(fields.dueAt).getTime():null});await load(cid);edit(data.assignments.find(row=>row.id===value.id));notify('Draft saved.');});};
  dialog.querySelector('[data-assign]')?.addEventListener('click',()=>{if(form.querySelector('[name=title]').value!==value.title||form.querySelector('[name=instructions]').value!==value.instructions||form.querySelector('[name=type]').value!==value.type||form.querySelector('[name=lessonId]').value!==value.lessonId||form.querySelector('[name=dueAt]').value!==local){error(Error('Save your draft changes before assigning.'));return;}assign(value);});
 }
 function assign(a){mount(`<div class="assignment-modal-head"><h2>Assign ${e(a.title)}</h2>${btn('Close','data-close',true)}</div><p class="assignment-plain-text">${e(a.instructions)}</p><p>Due ${e(date(a.dueAt))}. This will appear on the selected students’ and parents’ dashboards.</p><label><input type="checkbox" data-all checked> Select all students</label><form class="assignment-form"><div class="assignment-student-choices">${data.students.map(s=>`<label><input type="checkbox" name="learners" value="${e(s.id)}" checked> ${e(s.name)}</label>`).join('')}</div><div class="assignment-actions"><button type="submit" class="teacher-button">Assign to selected students</button>${btn('Back to draft','data-back',true)}</div></form>`);dialog.querySelector('[data-all]').onchange=event=>dialog.querySelectorAll('[name=learners]').forEach(c=>c.checked=event.target.checked);dialog.querySelector('[data-back]').onclick=()=>edit(a);dialog.querySelector('form').onsubmit=event=>{event.preventDefault();action(async()=>{await call(path(cid,a.id),{action:'activate',revision:a.revision,learners:new FormData(event.target).getAll('learners')});dialog.close();await load(cid);onChange();});};}
 async function refreshDetail(){detail=await call(path(cid,detail.assignment.id));}
 function recipients(){return teacher?markingQueue(detail.recipients,filter):detail.recipients;}
 function current(){return detail.recipients.find(r=>r.learnerId===selected);}
 async function open(id,aid,initialFilter='submitted',learner=''){
  if(frame)try{await flush();}catch(err){error(err);return;}clearFrame();seenVersions.clear();cid=id;filter=initialFilter;selected=learner;history='';page='';
  mount(`<div class="assignment-modal-head"><h2>Loading assignment…</h2>${btn('Close','data-close',true)}</div>`);popup();try{detail=await call(path(cid,aid));const queue=recipients();selected=selected&&detail.recipients.some(r=>r.learnerId===selected)?selected:queue[0]?.learnerId||'';await workspace();}catch(err){error(err);}
 }
 async function workspace(){
  const a=detail.assignment,queue=recipients(),r=current(),attempt=r?.attempts.find(s=>s.id===(history||r.attempt)),pages=attempt?.pages||[];
  mount(`<div class="assignment-modal-head"><div><h2>${e(a.title)}</h2><p>${e(a.className)} · Due ${e(date(a.dueAt))}</p></div>${btn('Close','data-close',true)}</div><details class="assignment-instructions" ${teacher?'':'open'}><summary>Instructions & due date</summary><p>${e(a.instructions||'No additional instructions.')}</p><p>Assigned ${e(date(a.assignedAt))} · Due ${e(date(a.dueAt))}</p></details>${teacher?`<div class="assignment-actions assignment-filters">${[['submitted','Submitted'],['outstanding','Unfinished'],['all','All students']].map(([id,label])=>btn(label,`data-queue="${id}" aria-pressed="${filter===id}"`,filter!==id)).join('')}<span>Counts represent students, including multi-page submissions.</span></div>`:''}<div class="assignment-marking-grid ${teacher?'':'assignment-family'}">${teacher?`<aside class="assignment-queue" aria-label="Student marking queue"><p>${filter==='submitted'?'Unmarked first · oldest submission first':'Students'} · ${queue.length}</p>${queue.map(row=>`<button type="button" data-student="${e(row.learnerId)}" aria-current="${row.learnerId===selected}"><strong>${e(row.name)}</strong><span>${e(assignmentStatus[row.status])}</span><small>${row.submittedAt?'Submitted '+e(date(row.submittedAt)):row.startedAt?'Started '+e(date(row.startedAt)):'Not started'}</small></button>`).join('')||'<p>No students in this queue.</p>'}</aside>`:''}<section class="assignment-submission">${r?`<div class="assignment-submission-head"><strong>${e(r.name)} · ${e(assignmentStatus[r.status])}</strong>${detail.recipients.length>1&&!teacher?`<label>Student<select data-family-student>${detail.recipients.map(row=>`<option value="${e(row.learnerId)}" ${row.learnerId===selected?'selected':''}>${e(row.name)}</option>`).join('')}</select></label>`:''}${r.attempts.length?`<label>Submission<select data-attempt>${r.attempts.map((at,i)=>`<option value="${e(at.id)}" ${attempt?.id===at.id?'selected':''}>Attempt ${i+1} · ${e(date(at.submittedAt))}</option>`).join('')}</select></label>`:''}</div><div class="assignment-actions">${teacher?btn('Previous','data-prev',true)+btn('Next unmarked','data-next',true):''}${!parent&&!teacher&&['assigned','revision'].includes(r.status)?btn(a.type==='reading'?'Confirm reading completed':'Submit notebook pages','data-submit')+(a.type==='written'?btn('Open work page','data-work',true):''):''}${teacher&&!r.attempt&&a.type==='written'?'<p>This student has not submitted work.</p>':''}</div><div class="assignment-pages" role="group" aria-label="Pages in submission">${pages.map((p,i)=>btn(e(p.title),`data-page="${e(p.id)}" aria-pressed="${(page||pages[0]?.id)===p.id}"`,(page||pages[0]?.id)!==p.id)).join('')}</div><div class="assignment-page-host">${a.type==='reading'?'<div class="assignment-empty">'+(attempt?'Reading completion confirmed.':'Reading task — no notebook submission required.')+'</div>':!attempt?'<div class="assignment-empty">'+(parent?'Work has not been submitted yet.':'Open your work page or submit existing notebook pages when ready.')+'</div>':''}</div><div class="assignment-feedback"><h3>Feedback</h3>${teacher&&attempt?.id===r.attempt&&['submitted','reviewed'].includes(r.status)?`<label>Teacher feedback<textarea data-feedback rows="2" maxlength="8000">${e(feedbackValue(r))}</textarea></label><div class="assignment-actions">${r.status==='submitted'?btn('Mark reviewed','data-review="reviewed"'):''}${btn('Return for revision','data-review="revision"',true)}</div>`:''}${attempt?.events.length?`<details class="assignment-feedback-history" open><summary>Published feedback history</summary>${attempt.events.map(ev=>`<article><strong>${e(assignmentStatus[ev.status])} · ${e(date(ev.at))}</strong><p>${e(ev.feedback||'Reviewed without a written comment.')}</p></article>`).join('')}</details>`:!teacher?'<p>No published feedback yet.</p>':''}</div>`:'<div class="assignment-empty">No students in this queue.</div>'}</section></div>`);
  const host=dialog.querySelector('.assignment-page-host');if(pages.length&&teacher){for(const p of pages){const key=attempt.id+':'+p.id;if(!seenVersions.has(key)){const record=await call(path(cid,a.id)+`/submissions/${selected}/${attempt.id}/pages/${p.id}`);seenVersions.set(key,record.page.version);}}}if(pages.length){page=pages.some(p=>p.id===page)?page:pages[0].id;displayFrame(host,selected,page,attempt.id);}else clearFrame();
  dialog.querySelector('[data-feedback]')?.addEventListener('input',ev=>{const key=draftKey();feedbackDrafts.set(key,ev.target.value);try{localStorage.setItem(key,ev.target.value);}catch{}});
  const switchTo=async fn=>action(async()=>{await flush();clearFrame();await fn();await workspace();});
  dialog.querySelectorAll('[data-student]').forEach(b=>b.onclick=()=>switchTo(()=>{selected=b.dataset.student;history='';page='';}));
  dialog.querySelector('[data-family-student]')?.addEventListener('change',ev=>switchTo(()=>{selected=ev.target.value;history='';page='';}));
  dialog.querySelectorAll('[data-queue]').forEach(b=>b.onclick=()=>switchTo(()=>{filter=b.dataset.queue;selected=recipients()[0]?.learnerId||'';history='';page='';}));
  dialog.querySelector('[data-attempt]')?.addEventListener('change',ev=>switchTo(()=>{history=ev.target.value;page='';}));
  dialog.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>switchTo(()=>{page=b.dataset.page;}));
  const previous=dialog.querySelector('[data-prev]'),next=dialog.querySelector('[data-next]'),at=queue.findIndex(row=>row.learnerId===selected);
  if(previous){previous.disabled=at<=0;previous.onclick=()=>switchTo(()=>{selected=queue[at-1].learnerId;history='';page='';});next.disabled=nextUnmarked(queue,at)<0;next.onclick=()=>switchTo(()=>{selected=queue[nextUnmarked(queue,at)].learnerId;history='';page='';});}
  dialog.querySelector('[data-work]')?.addEventListener('click',()=>action(async()=>{await flush();await call(path(cid,a.id),{action:'start',learnerId:selected});await refreshDetail();const work=await call(path(cid,a.id)+'/work?'+new URLSearchParams({learnerId:selected}));const pid=work.workspacePages[0];if(!pid)throw Error('Open your notebook to choose a work page.');displayFrame(host,selected,pid,null);notify('Work autosaves. Use Submit notebook pages when you are ready.');}));
  dialog.querySelector('[data-submit]')?.addEventListener('click',()=>action(submitChoices));
  dialog.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>action(async()=>{const feedback=dialog.querySelector('[data-feedback]').value;await flush();const versions={};for(const p of pages){versions[p.id]=seenVersions.get(attempt.id+':'+p.id);}await call(path(cid,a.id),{action:'review',learnerId:selected,attempt:attempt.id,reviewVersion:r.reviewVersion,status:b.dataset.review,feedback,pageVersions:versions});feedbackDrafts.delete(draftKey());try{localStorage.removeItem(draftKey());}catch{}await refreshDetail();await workspace();notify(b.dataset.review==='reviewed'?'Review published. Use Next unmarked to continue.':'Returned for revision. Feedback and this submission have been preserved.');if(teacher)await load(cid);onChange();}));
 }
 async function submitChoices(){
  await flush();clearFrame();const a=detail.assignment,r=current(),work=a.type==='written'?await call(path(cid,a.id)+'/work?'+new URLSearchParams({learnerId:selected})):null;
  mount(`<div class="assignment-modal-head"><h2>${a.type==='reading'?'Confirm reading':'Submit notebook pages'}</h2>${btn('Close','data-close',true)}</div><p>${e(a.title)} · Due ${e(date(a.dueAt))}</p><p>${a.type==='reading'?'Confirm that you have completed the assigned reading.':'Choose one to ten pages. They will count as one submission. Your teacher will mark a saved copy; your notebook stays editable.'}</p><form class="assignment-form">${work?`<div class="assignment-student-choices">${work.pages.map(p=>`<label><input type="checkbox" name="pages" value="${e(p.id)}" ${work.workspacePages.includes(p.id)?'checked':''}>${e(p.title)}</label>`).join('')}</div>`:'<label><input name="confirmed" type="checkbox" required> I have completed the reading.</label>'}<div class="assignment-actions"><button class="teacher-button" type="submit">${a.type==='reading'?'Confirm completed':'Submit selected pages'}</button>${btn('Back','data-back',true)}</div></form>`);dialog.querySelector('[data-back]').onclick=()=>action(workspace);
  dialog.querySelector('form').onsubmit=event=>{event.preventDefault();const form=event.target;action(async()=>{const ids=new FormData(form).getAll('pages');await call(path(cid,a.id),{action:'submit',confirmed:form.elements.confirmed?.checked===true,pages:ids.map(id=>({id,version:work.pages.find(p=>p.id===id).version}))});await refreshDetail();await workspace();notify('Submitted. Your pages are grouped as one submission.');onChange();});};
 }
 return {open,load,edit,clear(){epoch++;root?.replaceChildren();},isBusy:()=>busy||dialog.open};
}
export function createAssignmentDashboard({root,parent=false}){
 const workspace=createAssignments({root:document.createElement('div'),parent,onChange:()=>load()});let generation=0;
 async function load(){const n=++generation;try{const data=await api('/api/assignments');if(n!==generation)return;const rank={revision:0,assigned:1,submitted:2,reviewed:3};const rows=data.assignments.flatMap(a=>(a.recipients||[]).map(r=>({a,r}))).sort((x,y)=>rank[x.r.status]-rank[y.r.status]||(x.a.dueAt||Infinity)-(y.a.dueAt||Infinity));root.innerHTML=`<div class="assignment-heading"><div><h2>Assignments</h2><p>${parent?'Your child’s upcoming work and teacher feedback.':'Your next steps, submissions and teacher feedback.'}</p></div></div>${rows.length?`<div class="assignment-dashboard-grid">${rows.map(({a,r})=>`<article class="assignment-dashboard-card" data-status="${e(r.status)}"><span>${e(a.className)}${parent?' · '+e(r.name):''}</span><h3>${e(a.title)}</h3><p>${e(assignmentStatus[r.status])} · Due ${e(date(a.dueAt))}</p>${r.feedback?`<p class="assignment-feedback-preview">${e(r.feedback.slice(0,180))}</p>`:''}${btn(parent?'View assignment & feedback':['submitted','reviewed'].includes(r.status)?'View submission & feedback':'Open assignment',`data-assignment="${e(a.id)}" data-class="${e(a.classId)}" data-learner="${e(r.learnerId)}"`,true)}</article>`).join('')}</div>`:'<p>No assigned work yet.</p>'}`;root.querySelectorAll('[data-assignment]').forEach(b=>b.onclick=()=>workspace.open(b.dataset.class,b.dataset.assignment,'all',b.dataset.learner));}catch(err){root.textContent='Assignments: '+err.message;}}
 load();return {load};
}
